    jv_free(rt->home_value);
  if (rt->path_buf) {
    free(rt->path_buf);
  }
  memset(rt, 0, sizeof(*rt));
  rt->home_value = jv_invalid();
  rt->path_status = 0;
  rt->file_fd = -1;
  rt->loc_refct = 0;
  rt->mod_count = 0;
